import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Departments — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Departments — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/departments"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Departments — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/departments"}]]},"headers":[],"relativePath":"user-guide/departments.md","filePath":"user-guide/departments.md","lastUpdated":1788477803000}'),s={name:"user-guide/departments.md"};function o(i,e,l,d,m,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="departments-—-user-guide" tabindex="-1">Departments — User Guide <a class="header-anchor" href="#departments-—-user-guide" aria-label="Permalink to &quot;Departments — User Guide&quot;">​</a></h1><h2 id="who-can-use-departments" tabindex="-1">Who can use Departments <a class="header-anchor" href="#who-can-use-departments" aria-label="Permalink to &quot;Who can use Departments&quot;">​</a></h2><p>Your workspace must have the <strong>Departments</strong> module installed from Marketplace. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>manage_members</code>, <code>assign_manager</code>, <code>view_performance</code>, and so on).</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Departments</strong> from the sidebar, under the <strong>HR</strong> group.</p><ul><li>Search by name, slug, or description</li><li>Filter by status (Active / Inactive)</li><li>KPI cards summarize total, active, inactive, and departments with a manager</li><li>Workspace owners and admins see all departments</li><li>Department managers see departments they manage</li><li>Staff see departments they belong to</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New department</strong></li><li>Enter a name (required); optionally description, status, manager, users, and employees</li><li>Save</li></ol><p>The <strong>manager</strong> must be a user with a login. Workspace admins assign managers (you can assign yourself). One user can manage multiple departments. Department managers can update their department and members, but cannot reassign the manager role.</p><h2 id="members" tabindex="-1">Members <a class="header-anchor" href="#members" aria-label="Permalink to &quot;Members&quot;">​</a></h2><ul><li><strong>Users</strong> — workspace logins tagged to the department</li><li><strong>Employees</strong> — HR directory records tagged to the department (requires the Employees module)</li></ul><p>Employees without a linked login still appear on the roster for HR, but are excluded from Lead/Task performance until linked.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><p>Managers and admins can open a department record to see <strong>Users</strong>, <strong>Employees</strong>, and <strong>Performance</strong> sections:</p><ul><li>Headcount (users, employees, performance-eligible, unlinked)</li><li>Lead totals (open / won / lost) when Leads is installed</li><li>Task totals (open / completed / overdue) when Tasks is installed</li><li>Per-member breakdown for linked users; unlinked employees marked as not performance-eligible</li></ul><p>Lead and Task list pages are unchanged in this release — managers track team work from the Departments performance view.</p><h2 id="department-reports" tabindex="-1">Department reports <a class="header-anchor" href="#department-reports" aria-label="Permalink to &quot;Department reports&quot;">​</a></h2><p>Workspace owners and department managers can open <strong>Department reports</strong> from the HR sidebar.</p><ul><li>Choose a <strong>from / to</strong> date range and run the report</li><li>See leads (open / won / lost) and tasks (open / completed) per department</li><li>Owners see all active departments; managers see only departments they manage</li><li>Requires the Departments module and dashboard access</li></ul><p>You receive a <strong>weekly email and in-app notification</strong> with the prior week’s department summary when you are an owner or department manager.</p><h2 id="related-modules" tabindex="-1">Related modules <a class="header-anchor" href="#related-modules" aria-label="Permalink to &quot;Related modules&quot;">​</a></h2><ul><li>Install <strong>Employees</strong> to tag HR directory members into departments</li><li>Performance aggregates use <strong>Leads</strong> and <strong>Tasks</strong> when those modules are installed</li></ul>',22)])])}const g=t(s,[["render",o]]);export{u as __pageData,g as default};
